    {
      "name": "Fintype.sum_of_injective",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {κ : Type u_6} {ι : Type u_7} [inst : Fintype ι] [inst_1 : Fintype κ] [inst_2 : AddCommMonoid M]\n  (e : ι → κ),\n  Function.Injective e →\n    ∀ (f : ι → M) (g : κ → M), (∀ i ∉ Set.range e, g i = 0) → (∀ (i : ι), f i = g (e i)) → ∑ i, f i = ∑ j, g j"
    },
    {
      "name": "MvPolynomial.weightedTotalDegree_rename_of_injective",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : CommSemiring R] {σ : Type u_5} {τ : Type u_6} {e : σ → τ} {w : τ → ℕ} {P : MvPolynomial σ R},\n  Function.Injective e →\n    MvPolynomial.weightedTotalDegree w ((MvPolynomial.rename e) P) = MvPolynomial.weightedTotalDegree (w ∘ e) P"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.rename_isHomogeneous_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ} {f : σ → τ},\n  Function.Injective f → (((MvPolynomial.rename f) φ).IsHomogeneous n ↔ φ.IsHomogeneous n)"
    },
    {
      "name": "MvPolynomial.rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} → {R : Type u_4} → [inst : CommSemiring R] → (σ → τ) → MvPolynomial σ R →ₐ[R] MvPolynomial τ R"
    },
    {
      "name": "MvPolynomial.rename_psum",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Symmetric.Defs",
      "kind": "theorem",
      "type": "∀ {τ : Type u_2} (σ : Type u_5) (R : Type u_6) [inst : CommSemiring R] [inst_1 : Fintype σ] [inst_2 : Fintype τ] (n : ℕ)\n  (e : σ ≃ τ), (MvPolynomial.rename ⇑e) (MvPolynomial.psum σ R n) = MvPolynomial.psum τ R n"
    }
  ]
}

